package fr.enssat.unolingo.mguezenn_mphongsa.data

import kotlinx.serialization.Serializable

/**
 * House additions that are not in the TP files, read from `assets/characters/extras.json` (generated by
 * `tools/gen_characters.py`): confusable symbols for distractors and other accepted spellings (`si`, `nn`, `di`…).
 * Keyed by set name (lowercase) then by symbol.
 */
@Serializable
data class CharacterExtras(
    val hiragana: Map<String, Extra> = emptyMap(),
    val katakana: Map<String, Extra> = emptyMap(),
    val kanji: Map<String, Extra> = emptyMap(),
) {
    @Serializable
    data class Extra(
        val alternatives: List<String> = emptyList(),
        val similar: List<String> = emptyList(),
    )

    companion object {
        const val ASSET_PATH = "characters/extras.json"

        fun parse(text: String): CharacterExtras = tpJson.decodeFromString(text)
    }
}
